// src/ui/setup/worldParams.ts
var MAX_CARDS = 6;
function renderWorldParams(host, ctx2) {
  const { wizard, registries: reg } = ctx2;
  const world = wizard.state.world;
  host.replaceChildren();
  const options2 = [...reg.worldOptions.values()];
  const groups = [];
  for (const o of options2) if (!groups.includes(String(o.group))) groups.push(String(o.group));
  const scale = (o, chosen) => {
    const choices = o.choices;
    const at = Math.max(0, choices.findIndex((c) => c.id === chosen));
    const shown = h("span", { class: "alius-slider-value", "data-option-value": o.id }, choices[at].label);
    const input = h("input", { type: "range", min: "0", max: String(choices.length - 1), step: "1", value: String(at), "data-option": o.id });
    input.addEventListener("input", () => shown.textContent = choices[Math.round(Number(input.value))]?.label ?? "");
    input.addEventListener("change", () => wizard.setWorldOption(o.id, choices[Math.round(Number(input.value))].id));
    return h(
      "label",
      { class: "alius-slider alius-option", "data-option": o.id, ...analyzeNative(`worldOptions:${o.id}`, { choice: chosen }) },
      h("span", { class: "alius-slider-label" }, String(o.label)),
      input,
      shown
    );
  };
  const optionBlock = (o) => {
    const live3 = o.live === true;
    const chosen = world.options[o.id] ?? String(o.default);
    return h(
      "div",
      { class: "alius-world-option", "data-option": o.id },
      h(
        "div",
        { class: "alius-world-head" },
        h("h4", {}, String(o.label)),
        h(
          "span",
          { class: "alius-lock", "data-live": String(live3), title: live3 ? "This option can be changed during the campaign." : "This option is fixed when the campaign starts." },
          live3 ? "CHANGEABLE LATER" : "LOCKED AT START"
        )
      ),
      h("p", { class: "alius-dim" }, String(o.description)),
      o.choices.length > MAX_CARDS ? scale(o, chosen) : h("div", { class: "alius-cards" }, ...o.choices.map((c) => h("button", {
        type: "button",
        class: "alius-card alius-option alius-world-choice",
        "data-option": o.id,
        "data-id": c.id,
        "aria-pressed": String(chosen === c.id),
        ...analyzeNative(`worldOptions:${o.id}`, { choice: c.id }),
        onclick: () => wizard.setWorldOption(o.id, c.id)
      }, h("strong", {}, c.label), h("p", {}, c.description))))
    );
  };
  const modeHost = h("div", { class: "alius-world-mode" });
  renderModeSection(modeHost, wizard);
  const headStartHost = h("div", { class: "alius-world-head-start" });
  renderHeadStartSection(headStartHost, wizard);
  const developmentHost = h("div", { class: "alius-world-development" });
  renderDevelopmentSection(developmentHost, wizard);
  const lifeHost = h("div", { class: "alius-world-life" });
  renderLifeSection(lifeHost, wizard);
  const contentHost = h("div", { class: "alius-section alius-world-content" });
  renderContentSection(contentHost, { enabled: wizard.state.content.enabled, registries: reg, onChange: (enabled) => wizard.setContent(enabled) });
  const dynamicHost = h("div", { class: "alius-world-dynamic" });
  renderDynamicStep(dynamicHost, { wizard, registries: reg });
  const summary = wizard.worldSummary();
  host.append(h(
    "div",
    { class: "alius-setup-body alius-world" },
    h("h3", {}, "WORLD PARAMETERS"),
    h("p", { class: "alius-hint" }, "Set the world before the campaign starts. Locked options cannot be changed afterwards. Pick a preset and adjust any option."),
    h("div", { class: "alius-presets" }, ...[...reg.worldPresets.values()].map((p) => h("button", {
      type: "button",
      class: "alius-btn alius-option alius-world-preset",
      "data-id": p.id,
      "aria-pressed": String(world.preset === p.id),
      title: String(p.description),
      ...analyzeNative(`worldPresets:${p.id}`),
      onclick: () => wizard.applyPreset(String(p.id))
    }, String(p.name)))),
    ...groups.flatMap((g) => [
      h("h3", {}, g.toUpperCase()),
      ...options2.filter((o) => String(o.group) === g).map(optionBlock)
    ]),
    modeHost,
    headStartHost,
    developmentHost,
    lifeHost,
    contentHost,
    dynamicHost,
    h(
      "section",
      { class: "alius-section alius-world-summary" },
      h("h3", {}, "WHAT THIS CHANGES"),
      summary.length === 0 ? h("p", { class: "alius-dim" }, "Nothing differs from the default world.") : h("ul", {}, ...summary.map((line2) => h("li", {}, line2)))
    )
  ));
}

