// src/ui/shell/modal.ts
function createModalHost(layer) {
  let cancelCurrent = null;
  return {
    isOpen: () => cancelCurrent !== null,
    cancel: () => cancelCurrent?.(),
    show(opts) {
      cancelCurrent?.();
      const previousFocus = document.activeElement;
      return new Promise((resolve) => {
        const finish2 = (value) => {
          cancelCurrent = null;
          backdrop.remove();
          previousFocus?.focus?.();
          resolve(value);
        };
        const buttons = opts.actions.map(
          (a) => h("button", { type: "button", class: "alius-btn", disabled: a.disabled !== void 0, title: a.disabled, onclick: () => finish2(a.value) }, a.label)
        );
        const reasons = opts.actions.flatMap((a) => a.disabled !== void 0 ? [h("span", { class: "alius-modal-reason" }, `${a.label} \u2014 ${a.disabled}`)] : []);
        const dialog = h(
          "div",
          { class: "alius-modal", role: "dialog", "aria-modal": "true", "aria-label": opts.title },
          h("div", { class: "alius-modal-title" }, opts.title),
          h("div", { class: "alius-modal-body" }, opts.body),
          h("div", { class: "alius-modal-actions" }, ...buttons, ...reasons)
        );
        const backdrop = h("div", { class: "alius-modal-backdrop" }, dialog);
        layer.append(backdrop);
        cancelCurrent = () => finish2(null);
        buttons.find((b) => !b.disabled)?.focus();
      });
    }
  };
}

// src/ui/memory/fill.ts
function fillValue(state, build, settings, part) {
  const cfg = memoryConfig(state);
  switch (part) {
    case "facts": {
      const facts = buildKnowledge(state, settings).facts();
      const pinned = facts.filter((f) => f.pinned === true).length;
      return `${facts.length} / ${cfg.factsMax}${pinned > 0 ? ` (${pinned} pinned)` : ""}`;
    }
    case "dossiers":
      return String(Object.values(state.memory.dossiers ?? {}).filter((d) => d.own !== "" || d.shared !== "").length);
    case "chronicle":
      return String(state.memory.chronicle.length);
    case "memory_tokens":
      return `${build.memoryTokens} / ${cfg.memoryTokens}`;
    case "directive_tokens":
      return String(build.directiveTokens);
    case "save_size":
      return `${(JSON.stringify(state).length / 1024).toFixed(1)} KB`;
  }
}
var ROWS = [
  ["facts", "Facts kept"],
  ["dossiers", "Dossiers"],
  ["chronicle", "Chronicle entries"],
  ["memory_tokens", "Memory in the last prompt (tokens)"],
  ["directive_tokens", "Directives in the last prompt (tokens)"],
  ["save_size", "Save size"]
];
function renderFill(host, state, build, settings) {
  host.replaceChildren(h("div", { class: "alius-memory-fill" }, ...ROWS.map(([part, label2]) => h(
    "div",
    { class: "alius-memory-row" },
    h("span", { class: "alius-field-label" }, label2),
    h("span", { class: "alius-stat", "data-fill": part, ...analyzeAttrs("glossary:memory_fill", { part }) }, fillValue(state, build, settings, part))
  ))));
}

// src/ui/memory/memorySection.ts
var PRESETS3 = ["short", "normal", "long", "custom"];
